//! Involute spur gear geometry, and the rack-generation engine that timing
//! pulleys share.
//!
//! Tooth outlines are generated by simulating the basic-rack cutter rolling
//! on the pitch circle, the way a hob or a rack-type shaper cuts them. The
//! root fillet trochoid and any undercut therefore come out exactly, instead
//! of being faked by joining an involute to a root arc.
//!
//! Conventions: millimetres, angles in degrees in `GearParams` and radians
//! everywhere else. A gear's local outline is centred on the origin with
//! tooth 0 pointing along +X.

use crate::bevel::{Bevel, BevelGeom};
use crate::hypoid::Role;
use crate::pulley::{self, BeltSection};
use crate::worm;
use serde::{Deserialize, Serialize};
use std::f64::consts::{PI, TAU};

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(default)]
pub struct GearParams {
    /// Module (pitch diameter / teeth), mm.
    pub module: f64,
    pub teeth: u32,
    /// Pressure angle of the basic rack, degrees.
    pub pressure_angle: f64,
    /// Profile shift coefficient x (rack moved outward by x * module).
    pub profile_shift: f64,
    /// Addendum coefficient ha*.
    pub addendum: f64,
    /// Dedendum coefficient hf*.
    pub dedendum: f64,
    /// Rack tip radius coefficient rho_f*.
    pub root_fillet: f64,
    /// When not Custom, ha*, hf* and rho_f* follow this standard.
    #[serde(default)]
    pub standard: ToothStandard,
    /// Tooth thinning at the pitch circle, circular mm. A pair's
    /// backlash is the sum of both gears' thinning.
    pub backlash: f64,
    /// Bore diameter, mm. 0 means no bore.
    pub bore: f64,
    pub face_width: f64,
    /// Set for a timing pulley: the belt section it takes. The pitch then
    /// comes from the section, `module` holds pitch / π, and the gear-only
    /// fields above are unused.
    #[serde(default)]
    pub belt: Option<BeltSection>,
    /// Belt width, mm (pulleys only).
    #[serde(default)]
    pub belt_width: f64,
    /// Set for a straight bevel gear: its pitch cone, which the solve
    /// derives from the mate. `module` is then the large-end module and
    /// `face_width` runs along the cone.
    #[serde(default)]
    pub bevel: Option<Bevel>,
    /// Set for half of a hypoid or spiral bevel set. The pair's geometry
    /// lives on the ring gear's placement; the ring's `module` (heel),
    /// `pressure_angle`, `face_width` and `backlash` set the teeth.
    #[serde(default)]
    pub hypoid: Option<Role>,
    /// Set with `hypoid` on both halves of a bevel worm set: a spiral bevel
    /// or hypoid pair whose pinion (the worm) has only 3 to 7 teeth, its
    /// starts.
    #[serde(default)]
    pub worm: bool,
    /// Set for half of a cylindrical worm drive. The pair's geometry lives
    /// on the wheel's placement; the wheel's `module` (the worm's axial
    /// module), `pressure_angle` (normal), `face_width` and `backlash` set
    /// the teeth, and the worm's `teeth` are its starts and its
    /// `face_width` its threaded length.
    #[serde(default)]
    pub worm_drive: Option<worm::Role>,
    /// The project's ball end mill Ø, mm, copied in by
    /// `Project::apply_ball`; 0 when none is chosen. The roots are rounded
    /// for it.
    #[serde(skip)]
    pub ball: f64,
}

impl Default for GearParams {
    fn default() -> Self {
        Self {
            module: 2.0,
            teeth: 24,
            pressure_angle: 20.0,
            profile_shift: 0.0,
            addendum: 1.0,
            dedendum: 1.25,
            root_fillet: 0.38,
            standard: ToothStandard::Iso53,
            backlash: 0.0,
            bore: 8.0,
            face_width: 10.0,
            belt: None,
            belt_width: 0.0,
            bevel: None,
            hypoid: None,
            worm: false,
            worm_drive: None,
            ball: 0.0,
        }
    }
}

/// Basic-rack proportions. Coefficients are per module (or per 1/DP,
/// which is the same thing in inch terms).
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Serialize, Deserialize)]
pub enum ToothStandard {
    /// Coefficients set by hand. Files from before standards existed load
    /// as Custom so their saved coefficients are kept.
    #[default]
    Custom,
    Iso53,
    AgmaFullDepth,
    Agma14_5,
    AgmaFinePitch,
    AgmaStub,
}

impl ToothStandard {
    pub const ALL: [ToothStandard; 6] = [
        ToothStandard::Iso53,
        ToothStandard::AgmaFullDepth,
        ToothStandard::Agma14_5,
        ToothStandard::AgmaFinePitch,
        ToothStandard::AgmaStub,
        ToothStandard::Custom,
    ];

    pub fn label(self) -> &'static str {
        match self {
            ToothStandard::Custom => "Custom",
            ToothStandard::Iso53 => "ISO 53 (metric)",
            ToothStandard::AgmaFullDepth => "AGMA full depth",
            ToothStandard::Agma14_5 => "AGMA 14½° full depth",
            ToothStandard::AgmaFinePitch => "AGMA fine pitch",
            ToothStandard::AgmaStub => "AGMA 20° stub",
        }
    }

    pub fn hint(self) -> &'static str {
        match self {
            ToothStandard::Custom => "Addendum, dedendum and fillet as entered under Rack.",
            ToothStandard::Iso53 => "Metric standard: addendum 1 m, dedendum 1.25 m, fillet 0.38 m.",
            ToothStandard::AgmaFullDepth => {
                "Coarse-pitch inch gears (under 20 DP), usually 20° or 25°: \
                 addendum 1/P, dedendum 1.25/P, fillet 0.3/P."
            }
            ToothStandard::Agma14_5 => {
                "Older Brown & Sharpe style inch gears, 14½°: addendum 1/P, dedendum 1.157/P, fillet 0.209/P."
            }
            ToothStandard::AgmaFinePitch => {
                "Inch gears of 20 DP and finer: addendum 1/P, dedendum 1.2/P + 0.002 in."
            }
            ToothStandard::AgmaStub => "Stronger, shorter teeth, 20°: addendum 0.8/P, dedendum 1/P.",
        }
    }

    /// (ha*, hf*, rho_f*) for a gear of module `m` mm.
    pub fn coefficients(self, m: f64) -> Option<(f64, f64, f64)> {
        Some(match self {
            ToothStandard::Custom => return None,
            ToothStandard::Iso53 => (1.0, 1.25, 0.38),
            ToothStandard::AgmaFullDepth => (1.0, 1.25, 0.3),
            ToothStandard::Agma14_5 => (1.0, 1.157, 0.209),
            // The 0.002 in constant becomes 0.0508 mm / m as a coefficient.
            ToothStandard::AgmaFinePitch => (1.0, 1.2 + 0.0508 / m, 0.3),
            ToothStandard::AgmaStub => (0.8, 1.0, 0.3),
        })
    }
}

pub fn inv(a: f64) -> f64 {
    a.tan() - a
}

/// Inverse of the involute function, by Newton iteration.
pub fn inv_inverse(y: f64) -> f64 {
    if y <= 0.0 {
        return 0.0;
    }
    let mut a = (3.0 * y).cbrt();
    for _ in 0..40 {
        let d = a.tan().powi(2);
        let next = (a - (inv(a) - y) / d).clamp(1e-9, 1.5);
        if (next - a).abs() < 1e-15 {
            return next;
        }
        a = next;
    }
    a
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Level {
    Warning,
    Error,
}

#[derive(Clone, Debug)]
pub struct Issue {
    pub level: Level,
    pub text: String,
}

impl Issue {
    pub(crate) fn warn(text: impl Into<String>) -> Self {
        Self { level: Level::Warning, text: text.into() }
    }
    pub(crate) fn error(text: impl Into<String>) -> Self {
        Self { level: Level::Error, text: text.into() }
    }
}

impl GearParams {
    /// Re-derive the rack coefficients from the tooth standard, or a
    /// pulley's equivalent module from its belt section.
    pub fn apply_standard(&mut self) {
        if let Some(b) = self.belt {
            self.module = b.pitch() / PI;
            return;
        }
        if let Some((ha, hf, rho)) = self.standard.coefficients(self.module) {
            self.addendum = ha;
            self.dedendum = hf;
            self.root_fillet = rho;
        }
    }

    pub fn alpha(&self) -> f64 {
        self.pressure_angle.to_radians()
    }
    pub fn pitch_radius(&self) -> f64 {
        self.module * self.teeth as f64 / 2.0
    }
    pub fn base_radius(&self) -> f64 {
        self.pitch_radius() * self.alpha().cos()
    }
    pub fn is_pulley(&self) -> bool {
        self.belt.is_some()
    }
    pub fn is_bevel(&self) -> bool {
        self.bevel.is_some()
    }
    pub fn is_hypoid(&self) -> bool {
        self.hypoid.is_some()
    }
    /// Teeth generated as a pair, off the UI thread: hypoid and spiral
    /// bevel sets, bevel worms and worm drives.
    pub fn is_generated(&self) -> bool {
        self.hypoid.is_some() || self.worm_drive.is_some()
    }
    /// A worm's thread count is its starts, kept to the worm's own range.
    pub fn is_worm_thread(&self) -> bool {
        (self.worm && self.hypoid == Some(Role::Pinion)) || self.worm_drive == Some(worm::Role::Worm)
    }
    /// Outside radius (a pulley's lies the pitch-line differential inside
    /// its pitch circle).
    pub fn tip_radius(&self) -> f64 {
        // A hypoid pinion grows with the offset; this is a generous bound.
        match self.hypoid {
            Some(Role::Ring) => return self.pitch_radius() + self.module,
            Some(Role::Pinion) => return 1.6 * self.pitch_radius() + 2.0 * self.module,
            None => {}
        }
        // The worm's diameter is on its wheel's placement: this is typical.
        match self.worm_drive {
            Some(worm::Role::Worm) => return worm::default_diameter(self.module) / 2.0 + self.module,
            Some(worm::Role::Wheel) => return self.pitch_radius() + 1.5 * self.module,
            None => {}
        }
        if let Some(g) = self.bevel.and_then(|_| BevelGeom::new(self)) {
            return g.outside_diameter() / 2.0;
        }
        match self.belt {
            Some(b) => self.pitch_radius() - b.rack(self.teeth).pld / 2.0,
            None => self.pitch_radius() + self.module * (self.addendum + self.profile_shift),
        }
    }
    pub fn root_radius(&self) -> f64 {
        match self.belt {
            Some(b) => self.tip_radius() - b.rack(self.teeth).hr,
            None => self.pitch_radius() - self.module * (self.cut_dedendum() - self.profile_shift),
        }
    }
    pub fn circular_pitch(&self) -> f64 {
        PI * self.module
    }
    /// Arc tooth thickness on the pitch circle.
    pub fn pitch_thickness(&self) -> f64 {
        self.module * (PI / 2.0 + 2.0 * self.profile_shift * self.alpha().tan()) - self.backlash
    }
    /// Arc tooth thickness of the involute flanks at radius `rr` (>= base).
    pub fn thickness_at(&self, rr: f64) -> f64 {
        let r = self.pitch_radius();
        let phi = (self.base_radius() / rr).clamp(-1.0, 1.0).acos();
        2.0 * rr * (self.pitch_thickness() / (2.0 * r) + inv(self.alpha()) - inv(phi))
    }
    /// Smallest profile shift that avoids undercut with this rack.
    pub fn min_shift_no_undercut(&self) -> f64 {
        self.addendum - self.teeth as f64 * self.alpha().sin().powi(2) / 2.0
    }
    /// Largest rack tip radius that still leaves a flat on the rack tip.
    pub fn max_fillet(&self) -> f64 {
        self.max_fillet_at(self.cut_dedendum())
    }

    fn max_fillet_at(&self, dedendum: f64) -> f64 {
        let a = self.alpha();
        let hw0 = (PI * self.module / 2.0 + self.backlash) / 2.0;
        ((hw0 - dedendum * self.module * a.tan()) * a.cos() / (1.0 - a.sin())).max(0.0)
    }

    /// The root fillet radius the spaces are cut with, mm: the ball's,
    /// or with none chosen the rack's.
    pub fn fillet(&self) -> f64 {
        if self.ball > 0.0 { self.ball / 2.0 } else { self.root_fillet * self.module }
    }

    /// Dedendum coefficient as cut: deep enough that the fillet rises no
    /// higher than the mate's tips reach (the rack's straight flank runs
    /// down past them), so a big ball deepens the roots. ISO's 0.38 m
    /// fillet rises 0.25003 m: a thousandth of a module is let pass.
    pub fn cut_dedendum(&self) -> f64 {
        let rise = self.fillet() * (1.0 - self.alpha().sin()) / self.module;
        self.dedendum.max(self.addendum + rise - 1e-3)
    }

    /// For a part cut on its own (not one of a generated pair): the ball
    /// end mill Ø its roots are rounded for as it stands, and the biggest
    /// that fits its spaces.
    pub fn ball_room(&self) -> Option<(f64, f64)> {
        if self.is_generated() || !self.is_buildable() {
            return None;
        }
        if let Some(b) = self.belt {
            let g = b.rack(self.teeth);
            let most = 0.999 * g.max_r1();
            return Some((2.0 * g.r1.max(self.ball / 2.0).min(most), 2.0 * most));
        }
        if self.is_bevel() {
            let g = BevelGeom::new(self)?;
            let toe = g.cone_distance * g.front_ratio();
            let now = g.fillet.map_or(0.0, |f| 2.0 * f.radius * toe);
            return Some((now, BevelGeom::largest_ball(self)?));
        }
        Some((2.0 * self.fillet().min(0.999 * self.max_fillet()), self.largest_ball()))
    }

    /// The biggest ball end mill Ø that rounds the roots, the rack tip a
    /// full round (the roots deepened to suit).
    pub fn largest_ball(&self) -> f64 {
        let m = self.module;
        let (sa, ca) = self.alpha().sin_cos();
        let a = self.max_fillet_at(self.dedendum);
        let lift = self.addendum - 1e-3;
        if a * (1.0 - sa) <= (self.dedendum - lift) * m {
            return 2.0 * a;
        }
        // Deepened: the fillet's rise is the dedendum past the addendum.
        let hw0 = (PI * m / 2.0 + self.backlash) / 2.0;
        2.0 * ((hw0 - lift * m * sa / ca) / ca).max(0.0)
    }

    pub fn is_buildable(&self) -> bool {
        if self.is_hypoid() {
            return self.module > 0.0 && self.teeth >= 3;
        }
        if self.worm_drive.is_some() {
            return self.module > 0.0 && self.teeth >= 1;
        }
        if self.is_bevel() {
            return BevelGeom::new(self).is_some();
        }
        if self.is_pulley() {
            return self.teeth >= 3 && self.root_radius() > 0.0;
        }
        self.module > 0.0
            && self.teeth >= 3
            && self.pressure_angle > 1.0
            && self.pressure_angle < 45.0
            && self.root_radius() > 0.0
            && self.tip_radius() > self.root_radius()
    }

    /// Problems with this gear; `len` formats a length in mm for display.
    pub fn issues(&self, len: impl Fn(f64) -> String) -> Vec<Issue> {
        let mut out = Vec::new();
        if self.is_generated() {
            // Checked as a pair, with the ring gear's or wheel's placement.
            return out;
        }
        if self.is_bevel() {
            match BevelGeom::new(self) {
                Some(g) => return g.issues(len),
                None => {
                    out.push(Issue::error("These parameters do not describe a bevel gear (check teeth, module and the cone)."));
                    return out;
                }
            }
        }
        if let Some(b) = self.belt {
            if !self.is_buildable() {
                out.push(Issue::error("Too few teeth to make a pulley."));
                return out;
            }
            if self.teeth < b.min_teeth() {
                out.push(Issue::warn(format!(
                    "ISO 5294 gives {} pulleys from {} teeth; smaller ones wear belts fast.",
                    b.name(),
                    b.min_teeth()
                )));
            }
            let g = b.rack(self.teeth);
            if self.ball / 2.0 > g.r1 + 1e-9 && self.ball / 2.0 <= 0.999 * g.max_r1() {
                out.push(Issue::warn(format!(
                    "The Ø{} ball end mill rounds the groove bottoms wider than ISO 5294's {}: check the belt's \
                     teeth still seat.",
                    len(self.ball),
                    len(g.r1)
                )));
            }
            let groove = g.hr;
            if self.bore > 0.0 && self.bore / 2.0 >= self.root_radius() - 0.5 * groove {
                out.push(Issue::warn("Bore leaves almost no material under the grooves."));
            }
            return out;
        }
        if !self.is_buildable() {
            out.push(Issue::error(
                "These parameters do not describe a gear (check module, teeth, \
                 pressure angle and dedendum).",
            ));
            return out;
        }
        let xmin = self.min_shift_no_undercut();
        if self.profile_shift < xmin - 1e-9 {
            out.push(Issue::warn(format!(
                "Undercut: the cutter removes part of the involute flank. \
                 Use profile shift ≥ {xmin:.3} to avoid it."
            )));
        }
        let tip_land = self.thickness_at(self.tip_radius());
        if tip_land <= 0.0 {
            out.push(Issue::error("Teeth are pointed: the flanks meet below the tip circle."));
        } else if tip_land < 0.25 * self.module {
            out.push(Issue::warn(format!("Narrow tip land ({}, under 0.25 × module).", len(tip_land))));
        }
        // A ball too big for the spaces is shown with its fix.
        if self.ball == 0.0 && self.root_fillet > self.max_fillet() + 1e-12 {
            out.push(Issue::warn(format!(
                "Root fillet limited to {:.3} × module by the rack geometry.",
                self.max_fillet() / self.module
            )));
        }
        if self.bore > 0.0 && self.bore / 2.0 >= self.root_radius() - 0.5 * self.module {
            out.push(Issue::warn("Bore leaves almost no material under the teeth."));
        }
        out
    }
}

/// Generated tooth: for each sampled radius, the half-angle of the tooth.
#[derive(Clone, Debug)]
pub struct Profile {
    pub radii: Vec<f64>,
    pub half: Vec<f64>,
}

const RADIAL_SAMPLES: usize = 140;

/// One tooth of a generating rack in rack coordinates: u along the rack,
/// v depth below the rolling line (towards the centre). Straight edges plus
/// arcs, convex or concave, kept as true arcs because a polygonal cutter
/// would leave facets in the fillets it cuts. The shape only needs to be
/// the cutter's material near the blank; edges beyond the blank never cut.
pub(crate) struct Rack {
    pub lines: Vec<[[f64; 2]; 2]>,
    /// Centre, radius, and the span of angles t (measured in the (u, v)
    /// frame) the arc covers.
    pub arcs: Vec<([f64; 2], f64, f64, f64)>,
    /// Largest |u| of the shape.
    pub extent: f64,
}

/// The basic rack for an involute gear: two straight flanks, rounded tip
/// corners, the tip flat, and a closing edge well clear of the blank. The
/// reference line is shifted out by x * module from the rolling line.
fn gear_rack(p: &GearParams) -> Rack {
    let m = p.module;
    let a = p.alpha();
    let (ca, ta) = (a.cos(), a.tan());
    let shift = p.profile_shift * m;
    let hw0 = (PI * m / 2.0 + p.backlash) / 2.0;
    let v_tip = p.cut_dedendum() * m;
    let v_top = -(p.addendum + 1.0) * m;
    let rho = p.fillet().clamp(0.0, p.max_fillet() * 0.999);
    let vc = v_tip - rho;
    let uc = hw0 - vc * ta - rho / ca;
    let top = [hw0 - v_top * ta, v_top];
    let mirror = |q: [f64; 2]| [-q[0], q[1]];

    let mut lines = Vec::new();
    let mut arcs = Vec::new();
    let flank_end;
    if rho > 0.0 {
        flank_end = [uc + rho * a.cos(), vc + rho * a.sin()];
        arcs.push(([uc, vc], rho, a, PI / 2.0));
        arcs.push(([-uc, vc], rho, PI / 2.0, PI - a));
    } else {
        flank_end = [hw0 - v_tip * ta, v_tip];
    }
    let tip_end = if rho > 0.0 { [uc, v_tip] } else { flank_end };
    lines.push([top, flank_end]);
    lines.push([mirror(top), mirror(flank_end)]);
    if tip_end[0] > 1e-12 {
        lines.push([tip_end, mirror(tip_end)]);
    }
    lines.push([mirror(top), top]);
    // Express everything below the rolling line rather than the shifted
    // reference line.
    for l in &mut lines {
        for q in l.iter_mut() {
            q[1] -= shift;
        }
    }
    for arc in &mut arcs {
        arc.0[1] -= shift;
    }
    Rack { lines, arcs, extent: top[0] }
}

fn record(half: &mut [f64], i: usize, x: f64, y: f64, tooth_centre: f64) {
    let delta = wrap(y.atan2(x) - tooth_centre);
    if delta < half[i] {
        half[i] = delta;
    }
}

/// Simulate the rack rolling through one tooth space and record, at each
/// radius, how close the cutter gets to the neighbouring tooth's centreline.
pub fn tooth_profile(p: &GearParams) -> Option<Profile> {
    if !p.is_buildable() {
        return None;
    }
    let m = p.module;
    let z = p.teeth as f64;
    let r = p.pitch_radius();
    let ra = p.tip_radius();
    let rf = p.root_radius();
    let half_pitch = PI / z;

    let mut radii: Vec<f64> = (0..=RADIAL_SAMPLES)
        .map(|i| {
            let s = i as f64 / RADIAL_SAMPLES as f64;
            rf + (ra - rf) * s * s
        })
        .collect();
    // Exactly at the root circle the rack tip is tangent and intersections
    // are ill-conditioned; nudge the first sample just above it.
    radii[0] = rf + 1e-7 * m;
    // Likewise at the top: a pulley rack's lands roll exactly on the
    // outside diameter.
    let last = radii.len() - 1;
    radii[last] = ra - 1e-7 * m;
    let mut half = vec![half_pitch; radii.len()];

    let rack = match p.belt {
        Some(b) => pulley::rack(b, p.teeth, p.ball),
        None => gear_rack(p),
    };
    let y_ref = r;
    let reach = (ra * ra - rf * rf).sqrt() + rack.extent + 2.0 * m;
    let phi_max = (reach / r).min(0.9 * PI);
    let steps = ((2.0 * reach / (m / 300.0)) as usize).clamp(600, 8000);
    // The space being cut is centred on +Y; the tooth whose flank we record
    // is the one clockwise of it.
    let tooth_centre = PI / 2.0 - half_pitch;

    for k in 0..=steps {
        let phi = -phi_max + 2.0 * phi_max * k as f64 / steps as f64;
        let (s, c) = phi.sin_cos();
        // Gear turns +phi, so the rack slides -r*phi; express that in the
        // gear's own (rotating) frame.
        let to_gear = |[u, v]: [f64; 2]| {
            let x = u - r * phi;
            let y = y_ref - v;
            [x * c + y * s, -x * s + y * c]
        };
        for &[a, b] in &rack.lines {
            let (a, b) = (to_gear(a), to_gear(b));
            let d = [b[0] - a[0], b[1] - a[1]];
            let dd = d[0] * d[0] + d[1] * d[1];
            let ad = a[0] * d[0] + a[1] * d[1];
            let aa = a[0] * a[0] + a[1] * a[1];
            let bb = b[0] * b[0] + b[1] * b[1];
            let t_near = if dd > 0.0 { (-ad / dd).clamp(0.0, 1.0) } else { 0.0 };
            let near = [a[0] + d[0] * t_near, a[1] + d[1] * t_near];
            let rmin = (near[0] * near[0] + near[1] * near[1]).sqrt();
            let rmax = aa.max(bb).sqrt();
            if rmax < radii[0] || rmin > ra || dd == 0.0 {
                continue;
            }
            let lo = radii.partition_point(|&q| q < rmin);
            let hi = radii.partition_point(|&q| q <= rmax);
            for i in lo..hi {
                let rr = radii[i];
                let disc = ad * ad - dd * (aa - rr * rr);
                if disc < 0.0 {
                    continue;
                }
                let sq = disc.sqrt();
                for t in [(-ad - sq) / dd, (-ad + sq) / dd] {
                    if (0.0..=1.0).contains(&t) {
                        record(&mut half, i, a[0] + d[0] * t, a[1] + d[1] * t, tooth_centre);
                    }
                }
            }
        }
        for &(centre, rho, t0, t1) in &rack.arcs {
            let cg = to_gear(centre);
            let dc = cg[0].hypot(cg[1]);
            if dc - rho > ra || dc + rho < radii[0] || dc < 1e-12 {
                continue;
            }
            let lo = radii.partition_point(|&q| q < dc - rho);
            let hi = radii.partition_point(|&q| q <= dc + rho);
            let (ux, uy) = (cg[0] / dc, cg[1] / dc);
            for i in lo..hi {
                // Circle-circle intersection: radius radii[i] about the
                // origin with radius rho about the cutter corner.
                let rr = radii[i];
                let along = (rr * rr - rho * rho + dc * dc) / (2.0 * dc);
                let h2 = rr * rr - along * along;
                if h2 < 0.0 {
                    continue;
                }
                let h = h2.sqrt();
                for sgn in [-1.0, 1.0] {
                    let x = ux * along - uy * h * sgn;
                    let y = uy * along + ux * h * sgn;
                    // Back to the rack frame to see if this point is on
                    // the corner arc rather than the rest of its circle.
                    let (gx, gy) = (x - cg[0], y - cg[1]);
                    let (fx, fy) = (gx * c - gy * s, gx * s + gy * c);
                    let t = (-fy).atan2(fx);
                    if t >= t0 - 1e-12 && t <= t1 + 1e-12 {
                        record(&mut half, i, x, y, tooth_centre);
                    }
                }
            }
        }
    }
    for h in &mut half {
        *h = h.clamp(0.0, half_pitch);
    }
    Some(Profile { radii, half })
}

fn wrap(a: f64) -> f64 {
    let mut a = a % TAU;
    if a > PI {
        a -= TAU;
    } else if a <= -PI {
        a += TAU;
    }
    a
}

fn polar(r: f64, a: f64) -> [f64; 2] {
    [r * a.cos(), r * a.sin()]
}

/// Points strictly between a0 and a1 on a circle, spaced about `step` mm.
fn arc_interior(out: &mut Vec<[f64; 2]>, r: f64, a0: f64, a1: f64, step: f64) {
    let segs = (((a1 - a0).abs() * r / step).ceil() as usize).max(1);
    for i in 1..segs {
        out.push(polar(r, a0 + (a1 - a0) * i as f64 / segs as f64));
    }
}

/// Closed outline of the whole gear, counter-clockwise, tooth 0 on +X.
pub fn outline(p: &GearParams, prof: &Profile) -> Vec<[f64; 2]> {
    let z = p.teeth as usize;
    let pitch = TAU / z as f64;
    let n = prof.radii.len();
    let step = p.module * 0.08;
    let mut out = Vec::with_capacity(z * (2 * n + 24));
    for k in 0..z {
        let c = k as f64 * pitch;
        for i in 0..n {
            out.push(polar(prof.radii[i], c - prof.half[i]));
        }
        let (rt, ht) = (prof.radii[n - 1], prof.half[n - 1]);
        arc_interior(&mut out, rt, c - ht, c + ht, step);
        for i in (0..n).rev() {
            out.push(polar(prof.radii[i], c + prof.half[i]));
        }
        let (r0, h0) = (prof.radii[0], prof.half[0]);
        arc_interior(&mut out, r0, c + h0, c + pitch - h0, step);
    }
    out
}

/// Triangulated fill for drawing: hub annulus plus one strip per tooth.
pub struct FillMesh {
    pub verts: Vec<[f64; 2]>,
    pub tris: Vec<[u32; 3]>,
}

pub fn fill_mesh(p: &GearParams, prof: &Profile) -> FillMesh {
    let z = p.teeth as usize;
    let pitch = TAU / z as f64;
    let mut verts = Vec::new();
    let mut tris = Vec::new();

    // Hub. Vertices sit slightly outside the root circle so the chords
    // between them do not leave slivers along the root arcs.
    let segs = (z * 8).max(96);
    let r_out = prof.radii[0] / (PI / segs as f64).cos();
    let r_in = (p.bore / 2.0).clamp(0.0, prof.radii[0] * 0.98);
    if r_in > 0.0 {
        for i in 0..segs {
            let a = i as f64 * TAU / segs as f64;
            verts.push(polar(r_in, a));
            verts.push(polar(r_out, a));
        }
        for i in 0..segs as u32 {
            let j = (i + 1) % segs as u32;
            tris.push([2 * i, 2 * i + 1, 2 * j + 1]);
            tris.push([2 * i, 2 * j + 1, 2 * j]);
        }
    } else {
        verts.push([0.0, 0.0]);
        for i in 0..segs {
            verts.push(polar(r_out, i as f64 * TAU / segs as f64));
        }
        for i in 0..segs as u32 {
            tris.push([0, 1 + i, 1 + (i + 1) % segs as u32]);
        }
    }

    // Teeth, from a thinned set of rows (the outline keeps full detail).
    let n = prof.radii.len();
    let mut rows: Vec<usize> = (0..n).step_by(3).collect();
    if *rows.last().unwrap() != n - 1 {
        rows.push(n - 1);
    }
    for k in 0..z {
        let c = k as f64 * pitch;
        let base = verts.len() as u32;
        for &i in &rows {
            verts.push(polar(prof.radii[i], c - prof.half[i]));
            verts.push(polar(prof.radii[i], c + prof.half[i]));
        }
        for j in 0..rows.len() as u32 - 1 {
            let (r0, l0, r1, l1) = (base + 2 * j, base + 2 * j + 1, base + 2 * j + 2, base + 2 * j + 3);
            tris.push([r0, r1, l1]);
            tris.push([r0, l1, l0]);
        }
        // Tip cap: fan from the middle of the top chord out to the arc.
        let (rt, ht) = (prof.radii[n - 1], prof.half[n - 1]);
        let a = polar(rt, c - ht);
        let b = polar(rt, c + ht);
        let mid = verts.len() as u32;
        verts.push([(a[0] + b[0]) / 2.0, (a[1] + b[1]) / 2.0]);
        let first = verts.len() as u32;
        let cap = 8;
        for i in 0..=cap {
            verts.push(polar(rt, c - ht + 2.0 * ht * i as f64 / cap as f64));
        }
        for i in 0..cap as u32 {
            tris.push([mid, first + i, first + i + 1]);
        }
    }
    FillMesh { verts, tris }
}

/// How two external gears run together.
#[derive(Clone, Debug)]
pub struct MeshInfo {
    pub standard_center: f64,
    pub center: f64,
    /// Working pressure angle, radians.
    pub working_pa: f64,
    pub contact_ratio: f64,
    /// Smallest tip-to-root clearance of the pair.
    pub clearance: f64,
    pub backlash: f64,
    pub mismatch: bool,
    /// One of the pair is a pulley, which cannot mesh with anything.
    pub pulley: bool,
}

pub fn mesh(a: &GearParams, b: &GearParams) -> MeshInfo {
    let m = a.module;
    let alpha = a.alpha();
    let zs = (a.teeth + b.teeth) as f64;
    let inv_w = inv(alpha) + 2.0 * alpha.tan() * (a.profile_shift + b.profile_shift) / zs;
    let working_pa = inv_inverse(inv_w);
    let standard_center = m * zs / 2.0;
    let center = standard_center * alpha.cos() / working_pa.cos();
    let path = |g: &GearParams| (g.tip_radius().powi(2) - g.base_radius().powi(2)).max(0.0).sqrt();
    let contact_ratio = (path(a) + path(b) - center * working_pa.sin()) / (PI * m * alpha.cos());
    let clearance = (center - a.tip_radius() - b.root_radius()).min(center - b.tip_radius() - a.root_radius());
    MeshInfo {
        standard_center,
        center,
        working_pa,
        contact_ratio,
        clearance,
        backlash: a.backlash + b.backlash,
        mismatch: (a.module - b.module).abs() > 1e-9 || (a.pressure_angle - b.pressure_angle).abs() > 1e-9,
        pulley: a.is_pulley() || b.is_pulley(),
    }
}

impl MeshInfo {
    pub fn issues(&self, module: f64, len: impl Fn(f64) -> String) -> Vec<Issue> {
        let mut out = Vec::new();
        if self.pulley {
            out.push(Issue::error("Pulleys don't mesh: connect them with a belt instead."));
            return out;
        }
        if self.mismatch {
            out.push(Issue::error("Module and pressure angle must match the gear this one meshes with."));
        }
        if self.contact_ratio < 1.0 {
            out.push(Issue::error(format!(
                "Contact ratio {:.2} is below 1: the teeth lose contact.",
                self.contact_ratio
            )));
        } else if self.contact_ratio < 1.2 {
            out.push(Issue::warn(format!("Low contact ratio ({:.2}); aim for 1.2 or more.", self.contact_ratio)));
        }
        if self.clearance < 0.1 * module {
            out.push(Issue::warn(format!(
                "Tip clearance only {}. Large profile shifts need the tips shortened.",
                len(self.clearance)
            )));
        }
        out
    }
}

/// How much of the ball fits against every point of a space's root,
/// at worst: the profile given seam to tip as (height off the floor,
/// distance from the space's middle), both mm in the plane square to
/// the tooth, the space being mirrored about its middle.
#[cfg(test)]
pub(crate) fn ball_fits(pts: &[[f64; 2]], ball: f64) -> f64 {
    let whole: Vec<[f64; 2]> = pts.iter().rev().map(|p| [p[0], -p[1]]).chain(pts[1..].iter().copied()).collect();
    ball_fits_space(&whole, ball)
}

/// The same for a whole space, given tip to tip (left to right seen from
/// outside). 1 if a ball of radius `ball` can touch every point under 2
/// balls up from inside, less the bit the chords between the profile's
/// points cut off a curve (2 % of the ball, with them 0.2 mm apart round
/// 0.5 mm).
#[cfg(test)]
pub(crate) fn ball_fits_space(pts: &[[f64; 2]], ball: f64) -> f64 {
    let floor = pts.iter().map(|p| p[0]).fold(f64::MAX, f64::min);
    let near = |c: [f64; 2]| {
        pts.windows(2)
            .map(|w| {
                let (a, b) = (w[0], w[1]);
                let (dx, dy) = (b[0] - a[0], b[1] - a[1]);
                let k = (((c[0] - a[0]) * dx + (c[1] - a[1]) * dy) / (dx * dx + dy * dy).max(1e-300)).clamp(0.0, 1.0);
                (c[0] - a[0] - k * dx).hypot(c[1] - a[1] - k * dy)
            })
            .fold(f64::MAX, f64::min)
    };
    (1..pts.len() - 1)
        .filter(|&i| pts[i][0] - floor < 2.0 * ball)
        .map(|i| {
            // Square to the neighbours, give or take: the best of a fan.
            let (dy, du) = (pts[i + 1][0] - pts[i - 1][0], pts[i + 1][1] - pts[i - 1][1]);
            let a = (-dy).atan2(du);
            (-20..=20)
                .map(|k| {
                    let (s, c) = (a + (k as f64).to_radians()).sin_cos();
                    near([pts[i][0] + ball * c, pts[i][1] + ball * s]) / ball
                })
                .fold(f64::MIN, f64::max)
        })
        .fold(1.0, f64::min)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn half_at(prof: &Profile, rr: f64) -> f64 {
        let i = prof.radii.partition_point(|&q| q < rr);
        let (r0, r1) = (prof.radii[i - 1], prof.radii[i]);
        let t = (rr - r0) / (r1 - r0);
        prof.half[i - 1] + (prof.half[i] - prof.half[i - 1]) * t
    }

    #[test]
    fn generated_flank_matches_involute() {
        for (z, x, j) in [(24, 0.0, 0.0), (17, 0.3, 0.05), (40, -0.2, 0.1), (12, 0.5, 0.0)] {
            let p = GearParams { teeth: z, profile_shift: x, backlash: j, ..Default::default() };
            let prof = tooth_profile(&p).unwrap();
            let rb = p.base_radius();
            let ra = p.tip_radius();
            for f in [0.2, 0.5, 0.8, 0.98] {
                let rr = p.pitch_radius().max(rb) + (ra - p.pitch_radius().max(rb)) * f;
                let expect = p.thickness_at(rr) / (2.0 * rr);
                let got = half_at(&prof, rr);
                assert!((got - expect).abs() * rr < 2e-4, "z={z} x={x} r={rr}: {got} vs {expect}");
            }
        }
    }

    #[test]
    fn undercut_thins_the_lower_flank() {
        let p = GearParams { teeth: 8, ..Default::default() };
        let prof = tooth_profile(&p).unwrap();
        // Just above the base circle the cut tooth is thinner than the
        // involute would be.
        let rr = p.base_radius() * 1.01;
        assert!(half_at(&prof, rr) < p.thickness_at(rr) / (2.0 * rr) - 1e-3);
        assert!(p.issues(|v| format!("{v}")).iter().any(|i| i.text.starts_with("Undercut")));
    }

    #[test]
    fn old_files_keep_their_coefficients() {
        let p: GearParams = serde_json::from_str(r#"{"teeth": 30, "dedendum": 1.4}"#).unwrap();
        assert_eq!(p.standard, ToothStandard::Custom);
        assert_eq!(p.dedendum, 1.4);
    }

    #[test]
    fn agma_inch_proportions() {
        // 12 DP, 20 teeth, full depth: 1.6667 in pitch, 1.8333 in outside.
        let mut p = GearParams { module: 25.4 / 12.0, teeth: 20, standard: ToothStandard::AgmaFullDepth, ..Default::default() };
        p.apply_standard();
        assert!((2.0 * p.pitch_radius() / 25.4 - 20.0 / 12.0).abs() < 1e-12);
        assert!((2.0 * p.tip_radius() / 25.4 - 22.0 / 12.0).abs() < 1e-12);
        // 32 DP fine pitch: dedendum 1.2/32 + 0.002 in.
        let mut f = GearParams { module: 25.4 / 32.0, standard: ToothStandard::AgmaFinePitch, ..Default::default() };
        f.apply_standard();
        let ded_in = (f.pitch_radius() - f.root_radius()) / 25.4;
        assert!((ded_in - (1.2 / 32.0 + 0.002)).abs() < 1e-12);
    }

    #[test]
    fn standard_pair() {
        let a = GearParams { teeth: 20, ..Default::default() };
        let b = GearParams { teeth: 40, ..Default::default() };
        let mi = mesh(&a, &b);
        assert!((mi.center - 60.0).abs() < 1e-9);
        assert!((mi.contact_ratio - 1.64).abs() < 0.01, "{}", mi.contact_ratio);
        assert!((mi.clearance - 0.5).abs() < 1e-9);
    }

    #[test]
    fn shifted_pair_spreads_centres() {
        let a = GearParams { teeth: 12, profile_shift: 0.4, ..Default::default() };
        let b = GearParams { teeth: 30, profile_shift: 0.2, ..Default::default() };
        let mi = mesh(&a, &b);
        assert!(mi.center > mi.standard_center);
        assert!((inv(mi.working_pa) - inv(a.alpha()) - 2.0 * a.alpha().tan() * 0.6 / 42.0).abs() < 1e-12);
    }

    #[test]
    fn outline_is_closed_ccw_and_within_blank() {
        let p = GearParams::default();
        let prof = tooth_profile(&p).unwrap();
        let o = outline(&p, &prof);
        let area: f64 = (0..o.len())
            .map(|i| {
                let (a, b) = (o[i], o[(i + 1) % o.len()]);
                a[0] * b[1] - b[0] * a[1]
            })
            .sum::<f64>()
            / 2.0;
        assert!(area > 0.0);
        let rmax = o.iter().map(|q| q[0].hypot(q[1])).fold(0.0, f64::max);
        assert!(rmax <= p.tip_radius() + 1e-9);
    }

    /// A space of a spur gear or pulley as `ball_fits` takes it: from the
    /// middle of the root out, (height off the root, distance from the
    /// space's middle), in mm.
    fn space(p: &GearParams) -> Vec<[f64; 2]> {
        let prof = tooth_profile(p).unwrap();
        let mid = PI / p.teeth as f64;
        let r0 = prof.radii[0];
        std::iter::once([0.0, 0.0]).chain(prof.radii.iter().zip(&prof.half).map(|(&r, &h)| [r - r0, (mid - h) * r])).collect()
    }

    #[test]
    fn spur_roots_are_milled_by_the_ball() {
        for (teeth, ball) in [(12, 1.2), (24, 1.5), (40, 1.75), (60, 0.8)] {
            let p = GearParams { teeth, ball, ..Default::default() };
            assert!(ball <= p.largest_ball());
            let fits = ball_fits(&space(&p), ball / 2.0);
            assert!(fits > 0.97, "{teeth} teeth, Ø{ball}: only {fits:.3} of the ball fits");
            // A big ball deepens the roots so the flanks still run on
            // below the mate's tips.
            let rise = ball / 2.0 * (1.0 - p.alpha().sin());
            assert!(p.cut_dedendum() * p.module >= p.addendum * p.module + rise - 1e-2, "{teeth} teeth: not deepened");
        }
        // ISO's fillet leaves ISO's root.
        let iso = GearParams { ball: 2.0 * 0.38 * 2.0, ..Default::default() };
        assert_eq!(iso.cut_dedendum(), 1.25);
    }

    #[test]
    fn the_biggest_ball_is_a_full_round_root() {
        for teeth in [10, 24, 80] {
            let p = GearParams { teeth, ..Default::default() };
            let d = p.largest_ball();
            let at = |ball: f64| GearParams { ball, ..p.clone() };
            assert!(at(0.99 * d).fillet() < at(0.99 * d).max_fillet());
            assert!(at(1.01 * d).fillet() > at(1.01 * d).max_fillet());
        }
    }

    #[test]
    fn pulley_grooves_are_milled_by_the_ball() {
        for s in BeltSection::ALL {
            let z = s.stock_teeth()[4];
            let ball = 1.9 * s.rack(z).max_r1();
            let p = GearParams { belt: Some(s), teeth: z, module: s.pitch() / PI, ball, ..Default::default() };
            let fits = ball_fits(&space(&p), ball / 2.0);
            assert!(fits > 0.97, "{s:?} Ø{ball:.2}: only {fits:.3} of the ball fits");
        }
    }
}
